document.querySelectorAll('[data-scroll-target]').forEach(button=>{button.addEventListener('click',()=>{document.getElementById(button.dataset.scrollTarget)?.scrollIntoView({behavior:'smooth',block:'start'});});});document.querySelectorAll('[data-route]').forEach(button=>{button.addEventListener('click',()=>{if(window.parent!==window){parent.postMessage({namespace:'ctuav-demo',type:'route',route:button.dataset.route},'*');}else{window.location.href=button.dataset.route==='about'?'https://ctuav.global/en/about-ct-uav/':'https://ctuav.global/en/';}});});addEventListener('message',event=>{if(event.source!==parent||event.data?.namespace!=='ctuav-demo'||event.data.type!=='palette')return;const theme=event.data.theme;document.documentElement.dataset.theme=theme;document.body.dataset.theme=theme;document.querySelectorAll('.palette-button').forEach(button=>{button.classList.toggle('selected',button.dataset.palette===theme);button.setAttribute('aria-pressed',String(button.dataset.palette===theme));});});addEventListener('message',event=>{if(event.source===parent&&event.data?.namespace==='ctuav-demo'&&event.data.type==='view-active'&&event.data.active)scrollTo({top:0,behavior:'instant'});});"use strict";(()=>{document.querySelectorAll('[data-footer-route]').forEach((button)=>button.addEventListener('click',()=>{const route=button.dataset.footerRoute;if(window.ctuavDemo)window.ctuavDemo.navigate(route);else if(parent!==window)parent.postMessage({namespace:'ctuav-demo',type:'route',route},'*');}));})();